<!--
 * 字典项管理页面 — 字典项的分页列表、搜索、新增、编辑、删除
 *
 * @path apps\system-web\src\views\dict-item\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 字典项（列表页）
 * <p>消费后端契约 DictItemController（src/api/dictItem.ts，auto-generated by bash/gen-contract.py）的字典项列表页：
 * 分页查询 page、编辑/删除（remove）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { ElButton, ElMessage, ElMessageBox, ElTag } from 'element-plus';
import { h, onUnmounted } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { page, remove } from '#/api/dict-item';
import type { DictItemPageQuery, DictItemVO, PageQuery } from '#/api/models';

import DictItemForm from './dict-item-form.vue';

defineOptions({ name: 'DictItemManagement' });

/** 请求控制器，用于取消未完成的请求 */
const abortController = new AbortController();

/** 行类型：真实契约 DictItemVO（字段以 models.ts 为准） */
type DictItemRow = DictItemVO;

/** 分页查询参数：契约 DictItemPageQuery + 通用分页字段（models.ts PageQuery） */
type DictItemPageQueryParams = DictItemPageQuery & PageQuery;

/** 状态是否启用（后端 status 为字符串，兼容 '1' / 'ENABLED' 两种取值） */
function isEnabled(status?: string): boolean {
  return status === '1' || status === 'ENABLED';
}

const gridOptions: VxeTableGridOptions<DictItemRow> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'typeCode', title: '字典类型', width: 130 },
    { field: 'itemCode', title: '字典项编码', width: 130 },
    { field: 'itemValue', title: '字典值', width: 150 },
    { field: 'sortOrder', title: '排序', width: 80 },
    {
      field: 'status',
      title: '状态',
      width: 80,
      slots: {
        default: ({ row }) => {
          const item = row as DictItemRow;
          return h(
            ElTag,
            { type: isEnabled(item.status) ? 'success' : 'info' },
            () => (isEnabled(item.status) ? '启用' : '禁用'),
          );
        },
      },
    },
    { field: 'description', title: '描述', width: 200 },
    {
      field: 'action',
      title: '操作',
      width: 140,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          const item = row as DictItemRow;
          return h('div', { class: 'flex gap-1' }, [
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(item) }, () => '编辑'),
            h(ElButton, { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(item) }, () => '删除'),
          ]);
        },
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async ({ page: pageInfo }, formValues) => {
        const query: DictItemPageQueryParams = {
          pageNum: pageInfo.currentPage,
          pageSize: pageInfo.pageSize,
          ...formValues,
        };
        const res = await page({ query });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      { field: 'typeCode', title: '字典类型', itemRender: { name: 'Input', props: { placeholder: '字典类型编码' } } },
      { field: 'itemCode', title: '字典项编码', itemRender: { name: 'Input', props: { placeholder: '字典项编码' } } },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [DictItemFormModal, dictItemFormApi] = useYDSZModal({ connectedComponent: DictItemForm });

function handleAdd() {
  dictItemFormApi.open();
}

function handleEdit(row: DictItemRow) {
  dictItemFormApi.setData({ record: row });
  dictItemFormApi.open();
}

async function handleDelete(row: DictItemRow) {
  try {
    await ElMessageBox.confirm(`确定删除「${row.itemCode ?? row.itemValue ?? ''}」吗？`, '删除确认', { type: 'warning' });
    if (row.id) await remove({ id: row.id });
    ElMessage.success('删除成功');
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}

/** 页面卸载时取消未完成的请求 */
onUnmounted(() => {
  abortController.abort();
});
</script>

<template>
  <Page auto-content-height>
    <Grid table-title="字典项">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">新增</ElButton>
      </template>
    </Grid>
    <DictItemFormModal @success="gridApi.query()" />
  </Page>
</template>